SELECT id, report_date, health_record_count, high_risk_count,
       fraud_block_count, order_count, summary, create_time
FROM daily_report WHERE report_date = #{reportDate}

SELECT id, report_date, health_record_count, high_risk_count,
       fraud_block_count, order_count, summary, create_time
FROM daily_report ORDER BY report_date DESC LIMIT #{days}
